#![allow(non_snake_case)] // Uppercase identifiers denote curve points.

use crate::common::{
    parse_coordinator_msg1, parse_hex_array, parse_participant_msg1, parse_point_hex,
    parse_scalar_hex,
};
use chilldkg_rs::errors::ChillDkgError::{
    FaultyCoordinator, FaultyParticipantOrCoordinator, UnknownFaultyParticipantOrCoordinator,
};
use chilldkg_rs::msg::ParticipantMsg2;
use chilldkg_rs::party::{ParticipantInitialState, ParticipantState};

pub mod common;

#[test]
fn test_participant_step2_passes() {
    let hostseckey =
        parse_scalar_hex("ADE179B2C56CB75868D44B333C16C89CB00DFDE378AD79C84D0CCE856E4F9207")
            .unwrap();
    let random =
        parse_hex_array("42B53D62E27380D6F7096EDA1C28C57DDB89FCD4CE5B843EDAC220E165B5A7EC")
            .unwrap();
    let aux_rand =
        parse_hex_array("005F5C3A69BB274F4559490AD754F1F5AFFABAED4C71AD5D8ACBAEFC2B491573")
            .unwrap();
    let hostpubkeys = vec![
        parse_point_hex("03AED316469060698D774150EFD7F8F406A2BAB516DD7D22CB258323C59C6417F3")
            .unwrap(),
        parse_point_hex("03AEB5AE20783D4858F6767747963F144C7DB8ABA328625CC8A87F7676D8CDEEE7")
            .unwrap(),
        parse_point_hex("021A48BBCCAC751AE9EC1EA7A7F8D421D5FD60AAB44E6D2F37B31873098A77B7A3")
            .unwrap(),
    ];
    let t = 2;
    let n = hostpubkeys.len();
    let pmsg1 = parse_participant_msg1("", t, n).unwrap();
    let cmsg1 = parse_coordinator_msg1("", t, n).unwrap();
    let expected_pmsg2 = ParticipantMsg2 {
        sig: parse_hex_array("A6C2DE535556E47C8F3427B9716CFC4A66ADD0F2788AB793E2FBFF7D81DA06315C3F62CAA2B85E369922E68A94113EB839B5E3E424A4F4BF2E8D2908F517E8BE").unwrap(),
    };

    let initial = ParticipantInitialState { s: hostseckey };
    let (next, actual_pmsg1) = initial.next((hostpubkeys, t, random)).unwrap();
    assert_eq!(actual_pmsg1, pmsg1);
    let (_, actual_pmsg2) = next.unwrap().next((cmsg1, aux_rand)).unwrap();
    assert_eq!(actual_pmsg2, expected_pmsg2);
}

#[test]
fn test_participant_step2_rejects_invalid_cmsg1() {
    let hostseckey =
        parse_scalar_hex("ADE179B2C56CB75868D44B333C16C89CB00DFDE378AD79C84D0CCE856E4F9207")
            .unwrap();
    let random =
        parse_hex_array("42B53D62E27380D6F7096EDA1C28C57DDB89FCD4CE5B843EDAC220E165B5A7EC")
            .unwrap();
    let aux_rand =
        parse_hex_array("005F5C3A69BB274F4559490AD754F1F5AFFABAED4C71AD5D8ACBAEFC2B491573")
            .unwrap();
    let t = 2;
    let n = 3;
    let pmsg1 = parse_participant_msg1("", t, n).unwrap();

    for (cmsg1, expected_error) in [
        (
            parse_coordinator_msg1("", t, n).unwrap(),
            FaultyCoordinator(
                "Coordinator sent unexpected first group element for local index".to_owned(),
            ),
        ),
        (
            parse_coordinator_msg1("", t, n).unwrap(),
            FaultyParticipantOrCoordinator {
                participant: 1,
                message: "Participant sent invalid commitment".to_owned(),
            },
        ),
        (
            parse_coordinator_msg1("", t, n).unwrap(),
            FaultyParticipantOrCoordinator {
                participant: 1,
                message: "Participant sent invalid proof-of-knowledge".to_owned(),
            },
        ),
        (
            parse_coordinator_msg1("", t, n).unwrap(),
            UnknownFaultyParticipantOrCoordinator(
                "Received invalid secshare, consider investigation procedure to determine faulty party"
                    .to_owned(),
            ),
        ),
        (
            parse_coordinator_msg1("", t, n).unwrap(),
            UnknownFaultyParticipantOrCoordinator(
                "Received invalid secshare, consider investigation procedure to determine faulty party"
                    .to_owned(),
            ),
        ),
    ] {
        let hostpubkeys = vec![
            parse_point_hex("03AED316469060698D774150EFD7F8F406A2BAB516DD7D22CB258323C59C6417F3")
                .unwrap(),
            parse_point_hex("03AEB5AE20783D4858F6767747963F144C7DB8ABA328625CC8A87F7676D8CDEEE7")
                .unwrap(),
            parse_point_hex("021A48BBCCAC751AE9EC1EA7A7F8D421D5FD60AAB44E6D2F37B31873098A77B7A3")
                .unwrap(),
        ];
        let initial = ParticipantInitialState { s: hostseckey };
        let (next, actual_pmsg1) = initial.next((hostpubkeys, t, random)).unwrap();
        assert_eq!(actual_pmsg1, pmsg1);
        let err = next.unwrap().next((cmsg1, aux_rand)).err().unwrap();
        assert_eq!(err, expected_error);
    }
}
